def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows = {}
        for name in names:
            rows[name] = {row["version"]: row for row in packages[name]}

        domains = []
        for name in names:
            versions = sorted(v for v in rows[name]
                              if v not in blocked.get(name, [])
                              and (name not in pins or v == pins[name]))
            domains.append([-1] + versions)

        best = None
        best_vector = None

        def check(values):
            assigned = dict(zip(names, values))
            if any(assigned[name] == -1 or not
                   (bounds[0] <= assigned[name] <= bounds[1])
                   for name, bounds in data["roots"].items()):
                return False

            graph = {}
            reachable = set()
            stack = list(data["roots"])
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                version = assigned[name]
                if version == -1:
                    return False
                row = rows[name][version]
                edges = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    ov = assigned[other]
                    if ov == -1 or not dep["min"] <= ov <= dep["max"]:
                        return False
                    edges.append(other)
                    stack.append(other)
                graph[name] = edges
            if any(assigned[name] != -1 for name in names
                   if name not in reachable):
                return False

            done, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for other in graph.get(name, []):
                    if not visit(other):
                        return False
                active.remove(name)
                done.add(name)
                return True

            return all(visit(name) for name in reachable)

        def search(i, values):
            nonlocal best, best_vector
            if i == len(names):
                vector = tuple(values)
                if (best_vector is None or vector < best_vector) and check(values):
                    best_vector = vector
                    best = {name: value for name, value in zip(names, values)
                            if value != -1}
                return
            for version in domains[i]:
                search(i + 1, values + [version])

        search(0, [])
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}
    return solve


def _build_component_07():
    from itertools import combinations

    def solve(data):
        k = data["k"]
        jobs = data["jobs"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        options = [job for job in jobs if job["id"] not in blocked]
        best_ids = None
        best_value = None
        for subset in combinations(options, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["end"] > ordered[i + 1]["start"]
                   for i in range(len(ordered) - 1)):
                continue
            chosen_ids = sorted(ids)
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and chosen_ids < best_ids)):
                best_value, best_ids = value, chosen_ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        indexes = {node: i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = 0
        if data["source"] in indexes:
            initial_mask |= 1 << indexes[data["source"]]
        start_state = (data["source"], initial_mask, data["coupons"])
        start_time = data["start"]
        distance = {start_state: start_time}
        queue = [(start_time, data["source"], initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distance.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                next_mask = mask
                if edge["v"] in indexes:
                    next_mask |= 1 << indexes[edge["v"]]
                for duration, next_remaining in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_remaining)
                    if arrival < distance.get(next_state, float("inf")):
                        distance[next_state] = arrival
                        heapq.heappush(queue, (arrival, edge["v"], next_mask,
                                               next_remaining))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_component_01(),
    "component_02": _build_component_02(),
    "component_03": _build_component_03(),
    "component_04": _build_component_04(),
    "component_05": _build_component_05(),
